sys_script_include.script:
var hsbcTranSwiftLinking = Class.create();
hsbcTranSwiftLinking.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {


    validateOutcome: function() {
        try {

            var mandateOutcomes = gs.getProperty('x_hsb11_mss_c_proc.custody_Task_outcomes_mandate_check');
            var nonMandateOutcomes = gs.getProperty('x_hsb11_mss_c_proc.custody_Task_outcomes_non_mandate_check');
            var tskOutcome = this.getParameter('sysparm_tskOutcome');


            if (mandateOutcomes.indexOf(tskOutcome) > -1) {
                return 'Mandate';
            } else if (nonMandateOutcomes.indexOf(tskOutcome) > -1) {
                return 'NonMandate';
            } else {
                return 'HideField';
            }

        } catch (error) {
            gs.info('Error from hsbcTranSwiftLinking - validateOutcome  ' + error);

        }

    },

    validateTrade: function() {

        try {

            var market = this.getParameter('sysparm_dummy_trade_market');
            var refId = this.getParameter('sysparm_trade_ref_id');
            //  var gaServer = new GlideAggregate('x_hsb11_mss_c_proc_mss_custody_trade');
            //  gaServer.addNotNullQuery('transaction_reference');
            //  gaServer.addNotNullQuery('owning_business');
            //  gaServer.addEncodedQuery('trade_idLIKE' + refId + '^owning_business=' + market);
            //  gaServer.addAggregate('COUNT','transaction_reference');    // MSSCUSTODY-5188
            // gaServer.groupBy('trade_id');               			   // MSSCUSTODY-5188
            //  gaServer.query();


            var gaServer = new GlideRecord('sn_bom_trade');
            // gaServer.addNotNullQuery('ref_x_hsb11_mss_c_proc_mss_custody_trade_passive.transaction_reference');
            // gaServer.addNotNullQuery('ref_x_hsb11_mss_c_proc_mss_custody_trade_passive.owning_business');
            // gaServer.addNotNullQuery('ref_x_hsb11_mss_c_proc_mss_custody_trade.transaction_reference');
            // gaServer.addNotNullQuery('ref_x_hsb11_mss_c_proc_mss_custody_trade.owning_business');
            gaServer.addEncodedQuery('ref_x_hsb11_mss_c_proc_mss_custody_trade.trade_idLIKE' + refId + '^ref_x_hsb11_mss_c_proc_mss_custody_trade.owning_business=' + market + '^NQref_x_hsb11_mss_c_proc_mss_custody_trade_passive.trade_idLIKE' + refId + '^ref_x_hsb11_mss_c_proc_mss_custody_trade_passive.owning_business=' + market);
            gaServer.query();

        //    gs.info('chinmay before count');
            var myCount = gaServer.getRowCount();


            // if (gaServer.next()) {
            //     var myCount = gaServer.getAggregate('COUNT', 'transaction_reference'); // MSSCUSTODY-5188
            //     if (myCount == 1) {
            //         return gaServer.trade_id;
            //     } else if (myCount > 1) {
            //         return 'multiple';
            //     } else {
            //         return 'no record';
            //     }
            // }


            if (myCount == 1) {
                if (gaServer.next()) {

             //       gs.info('chinmay' + myCount);

             //       gs.info('Chinmay count is 1');
                    if (gaServer.sys_class_name == 'x_hsb11_mss_c_proc_mss_custody_trade') {
						new x_hsb11_mss_c_proc.MSSCustodyDataMigration().setSwiftLinkingFlag(gaServer.sys_id, true);
                        return gaServer.ref_x_hsb11_mss_c_proc_mss_custody_trade.trade_id;

                    } else if (gaServer.sys_class_name == 'x_hsb11_mss_c_proc_mss_custody_trade_passive') {
             //           gs.info("chinmay before calling migration script");
             //           gs.info('chinmay' + gaServer.ref_x_hsb11_mss_c_proc_mss_custody_trade_passive.trade_id);
						var tradeID = gaServer.ref_x_hsb11_mss_c_proc_mss_custody_trade_passive.trade_id;
                        //  var id = new x_hsb11_hsbc_mss_o.HSBC_Trade_and_Task_Migration().custRevertMigration(gaServer.ref_x_hsb11_mss_c_proc_mss_custody_trade_passive.trade_id);
                        var id = new x_hsb11_mss_c_proc.MSSCustodyDataMigration().revertMigration(gaServer.sys_id);
						new x_hsb11_mss_c_proc.MSSCustodyDataMigration().setSwiftLinkingFlag(gaServer.sys_id, true);

                        //gs.info('chinmay' + gaServer.u_id);



			//			gs.info('chinmay' + id);

                        return tradeID;


                    }
                }
            } else if (myCount > 1) {
             //   gs.info('chinmay inside multiple');
                return 'multiple';
            } else {
                return 'no record';
            }


        } catch (error) {
            gs.info('Error from hsbcTranSwiftLinking -validateTrade  ' + error);

        }

    },

    type: 'hsbcTranSwiftLinking'
});
